import heapq

def solve():
    grid_str = """
+ + + + + + + + + + + + + + + + + + +
+ + + + + + + + - - - - - - - - - - +
+ + + + + + + + - - - - - - - - - - +
+ + + + + - - - - - - - - - - @ - - +
+ - @ X - - - - - - - - - @ - - - - +
+ - @ + - - - - - - - @ - + X - - - +
+ - - - - - - - - - X - X + + - - - +
+ - - - - - - - - - - - - + + - - - +
+ - - + + - - - - - - - - + + - - + +
+ - - + + - - - @ - - - - - - - - - +
+ - - - - - - - - - * - - - - + - - +
+ - - - - - - - - - - - - - - + - - +
+ - X - - - - - - - - - - - - + + + +
+ - - + - - - - - - - - - - + + + + +
+ + - - - X - - - - $ - - + + + + + +
+ $ + - - - - @ - - - - - + + + + + +
+ + + + + - - - - - - - - X $ + + + +
+ + + + + + + - - - - - - - + + + + +
+ + + + + + + + + + + + + + + + + + +
"""
    grid = [line.split() for line in grid_str.strip().split('\n')]
    rows, cols = len(grid), len(grid[0])
    walls, goals, boxes, player_pos = set(), set(), set(), None
    for r in range(rows):
        for c in range(cols):
            char = grid[r][c]
            if char == '+': walls.add((r, c))
            elif char == 'X': goals.add((r, c))
            elif char == '@': boxes.add((r, c))
            elif char == '*': player_pos = (r, c)
            elif char == '$': boxes.add((r, c)); goals.add((r, c))
            elif char == '%': player_pos = (r, c); goals.add((r, c))

    def is_reachable(start, target, current_boxes):
        q = collections.deque([start])
        visited = {start}
        while q:
            curr = q.popleft()
            if curr == target: return True
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = curr[0]+dr, curr[1]+dc
                if (nr, nc) not in walls and (nr, nc) not in current_boxes and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return False

    def get_path(start, target, current_boxes):
        q = collections.deque([(start, "")])
        visited = {start}
        while q:
            curr, path = q.popleft()
            if curr == target: return path
            for dr, dc, m in [(-1,0,'U'),(1,0,'D'),(0,-1,'L'),(0,1,'R')]:
                nr, nc = curr[0]+dr, curr[1]+dc
                if (nr, nc) not in walls and (nr, nc) not in current_boxes and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), path + m))
        return None

    def get_heuristic(boxes):
        return sum(min(abs(b[0]-g[0]) + abs(b[1]-g[1]) for g in goals) for b in boxes)

    start_boxes = tuple(sorted(boxes))
    pq = [(get_heuristic(start_boxes), 0, player_pos, start_boxes, "")]
    visited = {(player_pos, start_boxes)}

    while pq:
        h, cost, p_pos, b_pos, path = heapq.heappop(pq)
        if set(b_pos) == goals: return path
        for i, (br, bc) in enumerate(b_pos):
            for dr, dc, move in [(-1,0,'U'),(1,0,'D'),(0,-1,'L'),(0,1,'R')]:
                # To push box i in direction (dr, dc), player must be at (br-dr, bc-dc)
                # and target position (br+dr, bc+dc) must be free
                push_from = (br-dr, bc-dc)
                push_to = (br+dr, bc+dc)
                if push_from not in walls and push_from not in b_pos and \
                   push_to not in walls and push_to not in b_pos:
                    if is_reachable(p_pos, push_from, b_pos):
                        player_move_path = get_path(p_pos, push_from, b_pos)
                        new_boxes = list(b_pos)
                        new_boxes[i] = push_to
                        new_boxes = tuple(sorted(new_boxes))
                        if (push_from, new_boxes) not in visited:
                            visited.add(((br, bc), new_boxes))
                            new_path = path + player_move_path + move
                            heapq.heappush(pq, (cost + 1 + get_heuristic(new_boxes), cost + 1, (br, bc), new_boxes, new_path))
    return "No Solution"

print(solve())
